using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tools that wrap a REST API via HttpClient.
/// Uses constructor injection for HttpClient and ILogger.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("List all available items from the API.")]
    public async Task<string> ListItems(
        [Description("Maximum number of items to return (1-100)")] int limit = 20,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing items with limit {Limit}", limit);
        var response = await httpClient.GetStringAsync($"/items?limit={limit}", cancellationToken);
        return response;
    }

    [McpServerTool, Description("Get a single item by its unique identifier.")]
    public async Task<string> GetItem(
        [Description("The unique ID of the item to retrieve")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching item {Id}", id);
        var response = await httpClient.GetAsync($"/items/{id}", cancellationToken);
        if (!response.IsSuccessStatusCode)
        {
            return $"Error: API returned {(int)response.StatusCode} {response.ReasonPhrase}";
        }
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool(Destructive = false, ReadOnly = true),
     Description("Search items by keyword query.")]
    public async Task<string> SearchItems(
        [Description("Search query string")] string query,
        [Description("Page number for pagination (starts at 1)")] int page = 1,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching items: {Query}, page {Page}", query, page);
        var encoded = Uri.EscapeDataString(query);
        var response = await httpClient.GetStringAsync(
            $"/items/search?q={encoded}&page={page}", cancellationToken);
        return response;
    }

    [McpServerTool(Destructive = true, Idempotent = false),
     Description("Create a new item with the given name and description.")]
    public async Task<string> CreateItem(
        [Description("Name for the new item")] string name,
        [Description("Optional description")] string? description = null,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating item: {Name}", name);
        var payload = JsonSerializer.Serialize(new { name, description }, JsonOptions);
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");
        var response = await httpClient.PostAsync("/items", content, cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            return $"Error: API returned {(int)response.StatusCode} {response.ReasonPhrase}";
        }
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

